package worldline.smoke.crosschunkwaterb173;

import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.time.Duration;import java.util.*;
import worldline.api.*;import worldline.b173server.*;

/** Opens a bounded official-water trench across one chunk seam. */
public final class CrossChunkWaterSmoke{
 private CrossChunkWaterSmoke(){}
 public static void main(String[]a)throws Exception{
  if(a.length!=11)throw new IllegalArgumentException("usage: CrossChunkWaterSmoke server.jar workspace port seed username sourceX neighborX chunkZ fixtureTicks flowTicks extra");Path jar=Paths.get(a[0]),workspace=Paths.get(a[1]);int port=Integer.parseInt(a[2]);long seed=Long.parseLong(a[3]);String user=a[4];int sourceX=Integer.parseInt(a[5]),neighborX=Integer.parseInt(a[6]),cz=Integer.parseInt(a[7]),fixtureTicks=Integer.parseInt(a[8]),flowTicks=Integer.parseInt(a[9]);require(neighborX==sourceX+1&&"m125".equals(a[10]),"M125 seam descriptor drift");Duration timeout=Duration.ofSeconds(90);B173DedicatedServer server=new B173DedicatedServer(jar,workspace,port,seed,timeout,3,true);B173WireClient actor=new B173WireClient("127.0.0.1",port,user,timeout),treatment=null,reader=null;RemoteChunkSnapshot left0,right0,left1,right1;BlockPosition foundation,top,source,target;BlockState opened,settled;int column;
  try{server.boot();B173PlayerSeed.writeInventory(workspace,user,sourceX*16+15.5D,60D,cz*16+6.5D,new int[]{0,1,2},new int[]{1,3,9},new int[]{48,1,1},new int[]{0,0,0});actor.connect();actor.synchronizePose();require(actor.awaitInventory().occupiedSlots()==3,"seam trench inventory drift");RemoteWorldView initialWorld=actor.awaitRemoteChunk(sourceX,cz);actor.sustainTicks(20);initialWorld=actor.awaitRemoteChunk(neighborX,cz);RemoteChunkSnapshot initial=initialWorld.chunkAt(sourceX,cz);foundation=foundation(initial,sourceX,cz);top=foundation;column=0;actor.selectHeldSlot(0);while(water(initial.blockAt(15,top.y()+1,top.z()-cz*16).legacyId())){top=place(actor,top,BlockFace.UP);actor.moveAndObserve(0D,1D,0D,1);column++;require(column<=15,"water column exceeded stack");}top=place(actor,top,BlockFace.UP);actor.moveAndObserve(0D,1D,0D,1);column++;BlockPosition west=place(actor,top,BlockFace.WEST),east=place(actor,top,BlockFace.EAST),east2=place(actor,east,BlockFace.EAST);List<BlockPosition>floor=new ArrayList<>(Arrays.asList(west,top,east,east2));for(BlockPosition p:new ArrayList<>(floor)){floor.add(place(actor,p,BlockFace.NORTH));floor.add(place(actor,p,BlockFace.SOUTH));}for(BlockPosition p:floor){int dx=p.x()-top.x(),dz=p.z()-top.z();if(dx==-1||dx==2||dz==-1||dz==1)place(actor,p,BlockFace.UP);}source=BlockFace.UP.adjacent(top);target=BlockFace.UP.adjacent(east);require(source.x()==sourceX*16+15&&target.x()==neighborX*16,"trench missed chunk seam");actor.selectHeldSlot(1);actor.placeHeldBlock(east,BlockFace.UP);actor.awaitBlock(target,new BlockState(3,0));actor.selectHeldSlot(2);actor.placeHeldBlock(top,BlockFace.UP);actor.awaitBlock(source,new BlockState(9,0));RemoteWorldView filled=actor.sustainTicks(5);require(filled.blockAt(source.x(),source.y(),source.z()).equals(new BlockState(9,0))&&filled.blockAt(target.x(),target.y(),target.z()).equals(new BlockState(3,0)),"seam water baseline drift");actor.selectHeldSlot(3);actor.moveAndObserve(0D,-2D,0D,2);actor.sustainTicks(fixtureTicks);actor.close();awaitPlayers(server,0);server.save();treatment=new B173WireClient("127.0.0.1",port,user,timeout);treatment.connect();treatment.synchronizePose();treatment.sustainTicks(20);RemoteWorldView before=treatment.awaitRemoteChunk(sourceX,cz);before=treatment.awaitRemoteChunk(neighborX,cz);left0=before.chunkAt(sourceX,cz);right0=before.chunkAt(neighborX,cz);treatment.beginBreak(target);Thread.sleep(3000L);treatment.finishBreak(target);opened=treatment.awaitBlock(target,new BlockState(0,0)).blockAt(target.x(),target.y(),target.z());settled=treatment.sustainTicks(flowTicks).blockAt(target.x(),target.y(),target.z());require(opened.equals(new BlockState(0,0))&&water(settled.legacyId()),"cross-chunk water absent");treatment.close();awaitPlayers(server,0);server.save();reader=new B173WireClient("127.0.0.1",port,user,timeout);reader.connect();reader.synchronizePose();reader.sustainTicks(20);RemoteWorldView after=reader.awaitRemoteChunk(sourceX,cz);after=reader.awaitRemoteChunk(neighborX,cz);left1=after.chunkAt(sourceX,cz);right1=after.chunkAt(neighborX,cz);require(left1.blockAt(15,source.y(),source.z()-cz*16).equals(new BlockState(9,0))&&right1.blockAt(0,target.y(),target.z()-cz*16).equals(settled),"fresh seam water drift");}finally{actor.close();if(treatment!=null)treatment.close();if(reader!=null)reader.close();server.close();}
  StateDelta left=delta(left0,left1),right=delta(right0,right1);require(left.changed==0&&right.changed==1,"cross-chunk water changed unrelated cells "+left+" / "+right);String evidence="column="+column+",source="+source.x()+":"+source.y()+":"+source.z()+":9:0,target="+target.x()+":"+target.y()+":"+target.z()+":3:0->0:0->"+settled.legacyId()+":"+settled.metadata()+",left="+left+",right="+right;String trace="v1|server=official-b1.7.3|seed="+seed+"|fixture=stone-trench-across-chunks+seeded-water9+dirt-gate3|seam="+sourceX+":"+neighborX+","+cz+"|settle="+fixtureTicks+"+"+flowTicks+"ticks|cause=packet14-open-neighbor-cell|confirmation=packet53-air|effect=official-horizontal-water-cross-chunk|observation=fresh-packet51-both-chunks|"+evidence+"|disconnect=clean";System.out.println("WORLDLINE_M125_WATER="+evidence);System.out.println("WORLDLINE_M125_TRACE="+trace);System.out.println("WORLDLINE_M125_SIGNATURE="+sha(trace));
 }
 private static BlockPosition place(B173WireClient a,BlockPosition support,BlockFace face)throws Exception{BlockPosition target=face.adjacent(support);a.placeHeldBlock(support,face);a.awaitBlock(target,new BlockState(1,0));return target;}private static BlockPosition foundation(RemoteChunkSnapshot q,int cx,int cz){for(int z=3;z<=12;z++)for(int y=126;y>=1;y--)if(q.blockAt(15,y,z).legacyId()==3&&water(q.blockAt(15,y+1,z).legacyId()))return new BlockPosition(cx*16+15,y,cz*16+z);throw new IllegalStateException("no seam trench foundation");}
 private static StateDelta delta(RemoteChunkSnapshot a,RemoteChunkSnapshot b)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");ByteBuffer row=ByteBuffer.allocate(10);int n=0;for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=0;y<128;y++)if(!a.blockAt(x,y,z).equals(b.blockAt(x,y,z))){BlockState p=a.blockAt(x,y,z),q=b.blockAt(x,y,z);n++;row.clear();row.putShort((short)x).putShort((short)y).putShort((short)z).put((byte)p.legacyId()).put((byte)p.metadata()).put((byte)q.legacyId()).put((byte)q.metadata());md.update(row.array());}return new StateDelta(n,hex(md.digest()));}
 private static boolean water(int id){return id==8||id==9;}private static void awaitPlayers(B173DedicatedServer s,int n)throws Exception{long end=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<end){if(s.players().size()==n)return;Thread.sleep(100);}throw new IllegalStateException("player count drift");}private static String sha(String s)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}private static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}private static void require(boolean v,String m){if(!v)throw new IllegalStateException(m);}private static final class StateDelta{final int changed;final String hash;StateDelta(int n,String h){changed=n;hash=h;}public String toString(){return changed+":"+hash;}}
}
